const body = $input.first()?.json?.body || $input.first()?.json || {};
const objectives = body.objectives || {};
const dependencies = body.dependencies || {};
const testWorkflow = body.testWorkflow || {};
const deploymentStrategy = body.deploymentStrategy || {};

const slug = String(objectives.slug || 'shelly_energy_guard').toLowerCase().replace(/[^a-z0-9_]/g, '_');
const name = String(objectives.name || 'Shelly Energy Guard');
const domain = String(objectives.domain || 'sensor');
const description = String(objectives.description || 'Home Assistant Python Sensor Module');
const targetEntities = Array.isArray(objectives.targetEntities) ? objectives.targetEntities : ['sensor.shellyplugsg3_e4b063e4bfd8_power'];

const systemPrompt = [
  'You are a Senior Home Assistant Python Developer.',
  'Generate a production-grade Python module (sensor.py) and unittest suite (test_' + slug + '.py) following the Thassi Module Template.',
  'Include resilient error handling for urllib.error.HTTPError, TimeoutError, and invalid sensor states (unavailable/unknown).',
  'Return valid JSON with keys: sensorPy, initPy, manifestJson, testPy.'
].join(' ');

return [{
  json: {
    slug,
    name,
    domain,
    description,
    targetEntities,
    unitOfMeasurement: objectives.unitOfMeasurement || 'W',
    icon: objectives.icon || 'mdi:lightning-bolt-circle',
    pollingIntervalSeconds: Number(objectives.pollingIntervalSeconds || 60),
    dependencies,
    testWorkflow,
    deploymentStrategy,
    geminiRequest: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{
        role: 'user',
        parts: [{ text: JSON.stringify({ objectives, dependencies, testWorkflow, deploymentStrategy }) }]
      }],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: 'application/json'
      }
    }
  }
}];
